import AppKit
import Carbon.HIToolbox
import XCTest

@testable import TilqosKit

/// P3: the clipboard is touched only by the commands that need it; the previous contents (all
/// items, all types) are saved and put back; content flagged concealed, transient or
/// auto-generated is neither read nor converted nor overwritten; text over 10,000 characters is
/// ignored and not kept. All of it runs against an in-memory pasteboard.
final class PrivacyClipboardTests: XCTestCase {
    private var scheduler: ManualScheduler!
    private var board: MemoryBoard!
    private var shortcuts: [UInt16] = []
    /// What the "other app" puts on the clipboard when it receives ⌘C.
    private var copiedByApp: [[String: Data]] = []
    private var scratch: ScratchDefaults!

    override func setUp() {
        scheduler = ManualScheduler()
        board = MemoryBoard()
        shortcuts = []
        copiedByApp = []
        scratch = ScratchDefaults.make()
    }

    override func tearDown() {
        scratch?.remove()
    }

    private func makeSelectionClipboard() -> SelectionClipboard {
        SelectionClipboard(board: board, scheduler: scheduler) { [unowned self] key in
            self.shortcuts.append(key)
            if key == UInt16(kVK_ANSI_C), !self.copiedByApp.isEmpty { self.board.set(self.copiedByApp) }
            return true
        }
    }

    /// Two items with several types each: not just text.
    private func richClipboard() -> [[String: Data]] {
        [
            [
                MemoryBoard.stringType: Data("old text".utf8),
                MemoryBoard.htmlType: Data("<b>old text</b>".utf8),
                "com.example.private-format": Data([1, 2, 3, 4]),
            ],
            ["public.file-url": Data("file:///tmp/x".utf8)],
        ]
    }

    private func copy(_ clipboard: SelectionClipboard) -> (text: String?, saved: SelectionClipboard.Saved?) {
        var result: (String?, SelectionClipboard.Saved?) = (nil, nil)
        var called = false
        clipboard.copySelection { text, saved in
            result = (text, saved)
            called = true
        }
        scheduler.advance(by: 1)
        XCTAssertTrue(called, "the completion always runs")
        return result
    }

    // MARK: - The rule

    func testEachMarkerMakesTheClipboardOffLimits() {
        for marker in [MemoryBoard.concealed, MemoryBoard.transient, MemoryBoard.autoGenerated] {
            let board = MemoryBoard()
            board.setText("hunter2", also: [marker])
            XCTAssertTrue(ClipboardPolicy.isSensitive(board), marker)
            XCTAssertEqual(ClipboardPolicy.readText(board), .refusedSensitive, marker)
            XCTAssertEqual(board.textReads, 0, "a refused clipboard's text is never read: \(marker)")
        }
    }

    func testMarkerOnAnySecondItemCounts() {
        board.set([[MemoryBoard.stringType: Data("a".utf8)], [MemoryBoard.concealed: Data()]])
        XCTAssertEqual(ClipboardPolicy.readText(board), .refusedSensitive)
    }

    func testOrdinaryTextIsReadable() {
        board.setText("ghbdtn")
        XCTAssertEqual(ClipboardPolicy.readText(board), .text("ghbdtn"))
        XCTAssertEqual(ClipboardPolicy.readText(MemoryBoard()), .empty)
    }

    func testTextLimitIsTenThousandCharacters() {
        board.setText(String(repeating: "a", count: 10_000))
        XCTAssertEqual(ClipboardPolicy.readText(board), .text(String(repeating: "a", count: 10_000)))
        board.setText(String(repeating: "a", count: 10_001))
        XCTAssertEqual(ClipboardPolicy.readText(board), .refusedTooLong)
        // Characters, not bytes: 10,000 two-byte letters are fine, 10,001 emoji are not.
        board.setText(String(repeating: "я", count: 10_000))
        XCTAssertNotEqual(ClipboardPolicy.readText(board), .refusedTooLong)
        board.setText(String(repeating: "😀", count: 10_001))
        XCTAssertEqual(ClipboardPolicy.readText(board), .refusedTooLong)
    }

    // MARK: - Borrowing the clipboard for a selection

    func testSelectionIsCopiedConvertedPastedAndTheOldClipboardComesBackInFull() {
        let original = richClipboard()
        board.set(original)
        copiedByApp = [[MemoryBoard.stringType: Data("ghbdtn".utf8)]]
        let clipboard = makeSelectionClipboard()

        let (text, saved) = copy(clipboard)
        XCTAssertEqual(text, "ghbdtn")
        XCTAssertEqual(shortcuts, [UInt16(kVK_ANSI_C)])

        clipboard.paste("привет", restoring: saved!)
        XCTAssertEqual(board.text, "привет")
        XCTAssertTrue(board.typeSet.contains(MemoryBoard.transient), "the temporary text is flagged for clipboard managers")
        XCTAssertEqual(shortcuts, [UInt16(kVK_ANSI_C), UInt16(kVK_ANSI_V)])

        scheduler.advance(by: 1)
        XCTAssertEqual(board.items, original, "every item and every type is back, byte for byte")
    }

    func testClipboardIsNotRestoredOverSomethingTheUserCopiedMeanwhile() {
        board.set(richClipboard())
        copiedByApp = [[MemoryBoard.stringType: Data("ghbdtn".utf8)]]
        let clipboard = makeSelectionClipboard()
        let (_, saved) = copy(clipboard)
        clipboard.paste("привет", restoring: saved!)
        board.setText("something new")  // the user copies again before the restore
        scheduler.advance(by: 1)
        XCTAssertEqual(board.text, "something new")
    }

    func testConcealedClipboardIsLeftAloneAndNoShortcutIsSent() {
        board.setText("correct horse battery staple", also: [MemoryBoard.concealed])
        copiedByApp = [[MemoryBoard.stringType: Data("ghbdtn".utf8)]]
        let before = board.items
        let (text, saved) = copy(makeSelectionClipboard())
        XCTAssertNil(text)
        XCTAssertNotNil(saved)
        XCTAssertEqual(shortcuts, [], "⌘C would have destroyed the password on the clipboard")
        XCTAssertEqual(board.items, before)
        XCTAssertEqual(board.textReads, 0)
        XCTAssertEqual(board.snapshots, 0, "and no copy of it was made")
    }

    func testConcealedSelectionIsDroppedUnreadAndTheClipboardRestored() {
        let original = richClipboard()
        board.set(original)
        // The selection comes from a password manager's field.
        copiedByApp = [[MemoryBoard.stringType: Data("s3cret".utf8), MemoryBoard.concealed: Data()]]
        let (text, _) = copy(makeSelectionClipboard())
        XCTAssertNil(text)
        XCTAssertEqual(board.textReads, 0, "the secret was never read")
        XCTAssertEqual(board.items, original, "the user's clipboard is back")
    }

    func testTransientAndAutoGeneratedSelectionsAreRefusedToo() {
        for marker in [MemoryBoard.transient, MemoryBoard.autoGenerated] {
            let original = richClipboard()
            board.set(original)
            copiedByApp = [[MemoryBoard.stringType: Data("x".utf8), marker: Data()]]
            XCTAssertNil(copy(makeSelectionClipboard()).text, marker)
            XCTAssertEqual(board.items, original, marker)
        }
    }

    func testOverlongSelectionIsIgnoredAndNotKept() {
        let original = richClipboard()
        board.set(original)
        copiedByApp = [[MemoryBoard.stringType: Data(String(repeating: "q", count: 10_001).utf8)]]
        let (text, _) = copy(makeSelectionClipboard())
        XCTAssertNil(text)
        XCTAssertEqual(board.items, original)
    }

    func testClipboardTooBigToPutBackIsNotBorrowed() {
        board.set(richClipboard())
        board.pretendSize = SelectionClipboard.saveLimit + 1
        copiedByApp = [[MemoryBoard.stringType: Data("ghbdtn".utf8)]]
        let before = board.items
        XCTAssertNil(copy(makeSelectionClipboard()).text)
        XCTAssertEqual(shortcuts, [], "overwriting what cannot be restored is not on")
        XCTAssertEqual(board.items, before)
    }

    func testNothingSelectedLeavesTheClipboardAlone() {
        let original = richClipboard()
        board.set(original)
        copiedByApp = []  // ⌘C copies nothing
        XCTAssertNil(copy(makeSelectionClipboard()).text)
        XCTAssertEqual(board.items, original)
    }

    // MARK: - The commands

    private final class Counter { var value = 0 }

    /// Never use `fixSelection()` or `transliterate(direction:)` here: they ask the system
    /// for the focused element first, and a test run must not touch whatever app is in front.
    private func makePipeline() -> (Pipeline, Counter) {
        let pipeline = Pipeline(
            prefs: Prefs(defaults: scratch.defaults), inputSources: CorpusTests.manager,
            models: CorpusTests.store, learner: Learner(defaults: scratch.defaults),
            board: board, scheduler: scheduler, panel: FakePresenter())
        pipeline.tap.secureInputProbe = { false }
        let beeps = Counter()
        pipeline.beep = { beeps.value += 1 }
        return (pipeline, beeps)
    }

    func testTransliterateClipboardConvertsOrdinaryText() throws {
        try XCTSkipIf(CorpusTests.store.model(for: .kk) == nil, "Models missing")
        let (pipeline, beeps) = makePipeline()
        board.setText("qalaisyz")
        pipeline.transliterateClipboard(direction: .toCyrillic)
        XCTAssertEqual(board.text, "қалайсыз")
        XCTAssertEqual(pipeline.undoCount, 1)
        XCTAssertEqual(pipeline.lastFix?.clipboardBefore, "qalaisyz")
        XCTAssertEqual(beeps.value, 0)

        pipeline.undoLastFix()
        XCTAssertEqual(board.text, "qalaisyz", "undo puts the clipboard text back")
    }

    func testCommandsRefuseAConcealedClipboard() throws {
        try XCTSkipIf(CorpusTests.store.model(for: .kk) == nil, "Models missing")
        let (pipeline, beeps) = makePipeline()
        board.setText("qalaisyz", also: [MemoryBoard.concealed])
        let before = board.items

        pipeline.transliterateClipboard(direction: .toCyrillic)
        pipeline.convertClipboard()
        XCTAssertEqual(board.items, before, "not converted")
        XCTAssertEqual(board.textReads, 0, "not read")
        XCTAssertEqual(pipeline.undoCount, 0, "no copy of it kept for undo")
        XCTAssertEqual(beeps.value, 2, "the user is told it did nothing")
    }

    func testCommandsIgnoreOverlongClipboardText() throws {
        try XCTSkipIf(CorpusTests.store.model(for: .kk) == nil, "Models missing")
        let (pipeline, _) = makePipeline()
        let long = String(repeating: "qalaisyz ", count: 1_200)  // 10,800 characters
        board.setText(long)
        pipeline.transliterateClipboard(direction: .toCyrillic)
        pipeline.convertClipboard()
        XCTAssertEqual(board.text, long, "left exactly as it was")
        XCTAssertEqual(pipeline.undoCount, 0, "and no copy of it kept")
    }

    // MARK: - The real pasteboard class, on a private one

    func testSystemPasteboardAdapterOnAPrivatePasteboard() throws {
        let name = NSPasteboard.Name("io.github.elapen.tilqos.test.\(UUID().uuidString)")
        let pasteboard = NSPasteboard(name: name)
        defer { pasteboard.releaseGlobally() }
        let adapter = NSPasteboardBoard(pasteboard)

        let first = NSPasteboardItem()
        first.setString("one", forType: .string)
        first.setData(Data([9, 8, 7]), forType: NSPasteboard.PasteboardType("com.example.custom"))
        let second = NSPasteboardItem()
        second.setString("two", forType: .string)
        pasteboard.clearContents()
        XCTAssertTrue(pasteboard.writeObjects([first, second]))

        XCTAssertFalse(ClipboardPolicy.isSensitive(adapter))
        let snapshot = try XCTUnwrap(adapter.snapshot(byteLimit: 1 << 20))
        XCTAssertEqual(snapshot.items.count, 2)
        XCTAssertEqual(snapshot.items[0]["com.example.custom"], Data([9, 8, 7]))

        // A password manager's copy.
        let secret = NSPasteboardItem()
        secret.setString("hunter2", forType: .string)
        secret.setData(Data(), forType: NSPasteboard.PasteboardType(MemoryBoard.concealed))
        pasteboard.clearContents()
        XCTAssertTrue(pasteboard.writeObjects([secret]))
        XCTAssertTrue(ClipboardPolicy.isSensitive(adapter))
        XCTAssertEqual(ClipboardPolicy.readText(adapter), .refusedSensitive)

        // Put the first contents back and compare.
        adapter.restore(snapshot)
        XCTAssertEqual(adapter.snapshot(byteLimit: 1 << 20)?.items.count, 2)
        XCTAssertEqual(adapter.plainText(), "one\ntwo", "the system joins the text of several items")

        // The temporary text of a paste is flagged transient and carries the text.
        adapter.replaceWithText("привет", transient: true)
        XCTAssertEqual(pasteboard.string(forType: .string), "привет")
        XCTAssertTrue(adapter.typeNames().contains(ClipboardPolicy.transientType))
        // Size cap.
        XCTAssertNil(adapter.snapshot(byteLimit: 3))
    }
}
